control "monitor_log_cluster_encrypted_with_cmk" {
  title       = "Azure Monitor Logs clusters should be encrypted with customer-managed key"
  description = "Create Azure Monitor logs cluster with customer-managed keys encryption. By default, the log data is encrypted with service-managed keys, but customer-managed keys are commonly required to meet regulatory compliance. Customer-managed key in Azure Monitor gives you more control over the access to you data, see https://docs.microsoft.com/azure/azure-monitor/platform/customer-managed-keys."
  query       = query.manual_control

  tags = merge(local.regulatory_compliance_monitor_common_tags, {
    nist_sp_800_53_rev_5 = "true"
  })
}

control "stream_analytics_job_encrypted_with_cmk" {
  title       = "Azure Stream Analytics jobs should use customer-managed keys to encrypt data"
  description = "Use customer-managed keys when you want to securely store any metadata and private data assets of your Stream Analytics jobs in your storage account. This gives you total control over how your Stream Analytics data is encrypted."
  query       = query.manual_control

  tags = merge(local.regulatory_compliance_streamanalytics_common_tags, {
    nist_sp_800_53_rev_5  = "true"
  })
}

control "security_center_defender_for_cloudposture_enabled" {
  title         = "Ensure Microsoft Defender CSPM is set to 'On'"
  description   = "Enable Microsoft Defender CSPM to continuously assess cloud resources for security misconfigurations, compliance risks, and exposure to threats."
  query         = query.security_center_defender_for_cloudposture_enabled

  tags = local.regulatory_compliance_securitycenter_common_tags
}

